package com.clothingstore;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.*; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class JwtService { private final SecretKey key; JwtService(@Value("${app.jwt-secret}") String secret){ if(secret.length()<32)throw new IllegalStateException("JWT_SECRET must contain at least 32 characters."); key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8)); } String create(UserAccount user){return Jwts.builder().subject(user.getEmail()).claim("role",user.getRole()).issuedAt(Date.from(Instant.now())).expiration(Date.from(Instant.now().plusSeconds(86400))).signWith(key).compact();} String email(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();} }
